public class MediaCapturePipelineFactory(string resourceName = null, Action<Humidifier.Chime.MediaCapturePipeline> factoryAction = null) : ResourceFactory<Humidifier.Chime.MediaCapturePipeline>(resourceName)
{

    internal InnerMediaCapturePipelineSseAwsKeyManagementParamsFactory SseAwsKeyManagementParamsFactory { get; set; }

    internal InnerMediaCapturePipelineChimeSdkMeetingConfigurationFactory ChimeSdkMeetingConfigurationFactory { get; set; }

    protected override Humidifier.Chime.MediaCapturePipeline Create()
    {
        var mediaCapturePipelineResult = CreateMediaCapturePipeline();
        factoryAction?.Invoke(mediaCapturePipelineResult);

        return mediaCapturePipelineResult;
    }

    private Humidifier.Chime.MediaCapturePipeline CreateMediaCapturePipeline()
    {
        var mediaCapturePipelineResult = new Humidifier.Chime.MediaCapturePipeline
        {
            GivenName = InputResourceName,
        };

        return mediaCapturePipelineResult;
    }
    public override void CreateChildren(Humidifier.Chime.MediaCapturePipeline result)
    {
        base.CreateChildren(result);

        result.SseAwsKeyManagementParams ??= SseAwsKeyManagementParamsFactory?.Build();
        result.ChimeSdkMeetingConfiguration ??= ChimeSdkMeetingConfigurationFactory?.Build();
    }

} // End Of Class

